import "server-only";
import { cookies } from "next/headers";
import type { Session } from "@formbricks/types/auth";
import type { TOrganizationRole } from "@formbricks/types/memberships";
import type { TWorkspace } from "@formbricks/types/workspace";
import { getOrganizationsByUserId } from "@/app/(app)/workspaces/[workspaceId]/lib/organization";
import { getWorkspacesByUserId } from "@/app/(app)/workspaces/[workspaceId]/lib/workspace";
import { IS_DEVELOPMENT, IS_FORMBRICKS_CLOUD } from "@/lib/constants";
import { FORMBRICKS_ORGANIZATION_ID_COOKIE, FORMBRICKS_WORKSPACE_ID_COOKIE } from "@/lib/localStorage";
import { getMembershipByUserIdOrganizationId } from "@/lib/membership/service";
import { getMonthlyOrganizationResponseCount, getOrganization } from "@/lib/organization/service";
import { getUser } from "@/lib/user/service";
import { getWorkspace } from "@/lib/workspace/service";
import { getSession } from "@/modules/auth/lib/session";
import { getEnterpriseLicense } from "@/modules/ee/license-check/lib/license";
import {
  getAccessControlPermission,
  getOrganizationWorkspacesLimit,
} from "@/modules/ee/license-check/lib/utils";

type TOrganizationWithBilling = NonNullable<Awaited<ReturnType<typeof getOrganization>>>;
type TLicense = Awaited<ReturnType<typeof getEnterpriseLicense>>;
type TUser = NonNullable<Awaited<ReturnType<typeof getUser>>>;

export interface TSettingsLayoutData {
  session: Session;
  user: TUser;
  organization: TOrganizationWithBilling;
  membershipRole?: TOrganizationRole;
  isAccessControlAllowed: boolean;
  isOwnerOrManager: boolean;
  isMultiOrgEnabled: boolean;
  organizationWorkspacesLimit: number;
  license: TLicense;
  responseCount: number;
  isFormbricksCloud: boolean;
  isDevelopment: boolean;
  // The "current" workspace used to render the sidebar's Workspace section, back link, and the
  // WorkspaceContext that reused settings components depend on. Null when the user has no workspace
  // (the org/account settings still render — Phase 2 handles that empty state).
  currentWorkspace: TWorkspace | null;
  backUrl: string;
}

/**
 * Resolves the organization for the routes that carry none in the URL (account settings), so opening
 * a profile/notifications page — and the reload after changing the language there — keeps the
 * sidebar, banners, back link and billing links on the organization the user is in instead of
 * switching a multi-organization user to their first one.
 *
 * The organization cookie wins when present: the proxy only keeps it while an organization-scoped
 * page (e.g. the landing page of an organization with no workspace yet) was visited after the last
 * workspace. Otherwise the organization of the last active workspace is the one the user is in.
 *
 * Both cookies outlive leaving an organization and the workspace cookie outlives deleting a
 * workspace, so each is only trusted while it still resolves to an organization the user is a
 * member of.
 */
const resolveActiveOrganizationId = async (
  userId: string,
  activeWorkspaceId: string | undefined,
  activeOrganizationId: string | undefined
): Promise<string | undefined> => {
  const organizations = await getOrganizationsByUserId(userId);

  if (activeOrganizationId && organizations.some((org) => org.id === activeOrganizationId)) {
    return activeOrganizationId;
  }

  if (activeWorkspaceId) {
    const activeWorkspace = await getWorkspace(activeWorkspaceId);
    if (activeWorkspace && organizations.some((org) => org.id === activeWorkspace.organizationId)) {
      return activeWorkspace.organizationId;
    }
  }

  return organizations[0]?.id;
};

/**
 * Assembles everything the shared settings shell (banners + sidebar + top bar) needs for the
 * org-scoped and account-scoped settings routes, where there is no `workspaceId` in the URL. All of
 * it is organization-level data, so no workspace is required to resolve it; we additionally surface
 * the user's first accessible workspace so the sidebar's Workspace section renders identically.
 *
 * `organizationId` is optional — account settings don't carry one, so it is resolved from the last
 * active organization or workspace (see `resolveActiveOrganizationId`).
 *
 * The "current" workspace is resolved from the same `formbricks-workspace-id` cookie (set by the
 * proxy from the last visited `/workspaces/[workspaceId]` path), so navigating into the
 * workspace-agnostic org-settings routes keeps the workspace you came from. If the cookie is missing
 * or points at a workspace the user can't access, it falls back to the first accessible workspace.
 */
export const getSettingsLayoutData = async (
  userId: string,
  organizationId?: string
): Promise<TSettingsLayoutData | null> => {
  const session = await getSession();
  if (!session?.user) return null;

  const cookieStore = await cookies();
  const activeWorkspaceId = cookieStore.get(FORMBRICKS_WORKSPACE_ID_COOKIE)?.value;
  const activeOrganizationId = cookieStore.get(FORMBRICKS_ORGANIZATION_ID_COOKIE)?.value;

  const orgId =
    organizationId ?? (await resolveActiveOrganizationId(userId, activeWorkspaceId, activeOrganizationId));
  if (!orgId) return null;

  const [user, organization, membership] = await Promise.all([
    getUser(userId),
    getOrganization(orgId),
    getMembershipByUserIdOrganizationId(userId, orgId),
  ]);
  if (!user || !organization || !membership) return null;

  const [isAccessControlAllowed, license, organizationWorkspacesLimit, workspaces] = await Promise.all([
    getAccessControlPermission(organization.id),
    getEnterpriseLicense(),
    getOrganizationWorkspacesLimit(organization.id),
    getWorkspacesByUserId(userId, organization.id),
  ]);

  const responseCount = IS_FORMBRICKS_CLOUD ? await getMonthlyOrganizationResponseCount(organization.id) : 0;

  // Resolve the workspace to display in the shell. Prefer the last active workspace when it belongs
  // to the accessible list; otherwise fall back to the first accessible workspace so the shell
  // always has something to show.
  const resolvedWorkspaceId =
    activeWorkspaceId && workspaces.some((w) => w.id === activeWorkspaceId)
      ? activeWorkspaceId
      : workspaces[0]?.id;
  // Full workspace object (not just id/name) so the shell can supply the WorkspaceContext.
  const currentWorkspace = resolvedWorkspaceId ? await getWorkspace(resolvedWorkspaceId) : null;
  const isOwnerOrManager = membership.role === "owner" || membership.role === "manager";

  return {
    session,
    user,
    organization,
    membershipRole: membership.role,
    isAccessControlAllowed,
    isOwnerOrManager,
    isMultiOrgEnabled: license.features?.isMultiOrgEnabled ?? false,
    organizationWorkspacesLimit,
    license,
    responseCount,
    isFormbricksCloud: IS_FORMBRICKS_CLOUD,
    isDevelopment: IS_DEVELOPMENT,
    currentWorkspace,
    // Without a workspace, "/" would root-redirect into the user's first organization; the landing
    // page keeps the user in the organization these settings were resolved for.
    backUrl: currentWorkspace
      ? `/workspaces/${currentWorkspace.id}/surveys`
      : `/organizations/${organization.id}/landing`,
  };
};

import "server-only";
import { cache as reactCache } from "react";
import { prisma } from "@formbricks/database";
import { Prisma, PrismaClient } from "@formbricks/database/prisma";
import { logger } from "@formbricks/logger";
import { ZString } from "@formbricks/types/common";
import { DatabaseError, UnknownError } from "@formbricks/types/errors";
import { TMembership, ZMembership } from "@formbricks/types/memberships";
import { reconcileOrganizationMembership } from "../authzed/organization-membership";
import { validateInputs } from "../utils/validate";

type TMembershipDbClient = PrismaClient | Prisma.TransactionClient;

type TDeferredMembershipProjection = Readonly<{
  projection: "deferred";
  transaction: Prisma.TransactionClient;
}>;

const getDbClient = (tx?: Prisma.TransactionClient): TMembershipDbClient => tx ?? prisma;

const getMembershipByUserIdOrganizationIdUncached = async (
  userId: string,
  organizationId: string,
  tx?: Prisma.TransactionClient
): Promise<TMembership | null> => {
  validateInputs([userId, ZString], [organizationId, ZString]);

  try {
    const membership = await getDbClient(tx).membership.findUnique({
      where: {
        userId_organizationId: {
          userId,
          organizationId,
        },
      },
    });

    if (!membership) return null;

    return membership;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      logger.error(error, "Error getting membership by user id and organization id");
      throw new DatabaseError(error.message);
    }

    throw new UnknownError("Error while fetching membership");
  }
};

const getMembershipByUserIdOrganizationIdCached = reactCache(async (userId: string, organizationId: string) =>
  getMembershipByUserIdOrganizationIdUncached(userId, organizationId)
);

export const getMembershipByUserIdOrganizationId = async (
  userId: string,
  organizationId: string,
  tx?: Prisma.TransactionClient
): Promise<TMembership | null> => {
  if (tx) {
    return getMembershipByUserIdOrganizationIdUncached(userId, organizationId, tx);
  }

  return getMembershipByUserIdOrganizationIdCached(userId, organizationId);
};

export const createMembership = async (
  organizationId: string,
  userId: string,
  data: Partial<TMembership>,
  options?: TDeferredMembershipProjection
): Promise<TMembership> => {
  validateInputs([organizationId, ZString], [userId, ZString], [data, ZMembership.partial()]);

  let membership: TMembership;

  try {
    const prismaClient = getDbClient(options?.transaction);
    const existingMembership = await prismaClient.membership.findUnique({
      where: {
        userId_organizationId: {
          userId,
          organizationId,
        },
      },
    });

    if (existingMembership && existingMembership.role === data.role) {
      membership = existingMembership;
    } else if (!existingMembership) {
      membership = await prismaClient.membership.create({
        data: {
          userId,
          organizationId,
          accepted: data.accepted,
          role: data.role as TMembership["role"],
        },
      });
    } else {
      membership = await prismaClient.membership.update({
        where: {
          userId_organizationId: {
            userId,
            organizationId,
          },
        },
        data: {
          accepted: data.accepted,
          role: data.role as TMembership["role"],
        },
      });
    }
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }

  // Transactional callers must project only after their outer transaction commits. Non-transactional
  // callers reconcile even on an idempotent retry so a repeated source mutation can heal SpiceDB.
  if (!options) {
    await reconcileOrganizationMembership(organizationId, userId);
  }

  return membership;
};

import { cache as reactCache } from "react";
import { prisma } from "@formbricks/database";
import { Prisma } from "@formbricks/database/prisma";
import { ZString } from "@formbricks/types/common";
import { DatabaseError, ResourceNotFoundError } from "@formbricks/types/errors";
import { lookupAuthorizedOrganizationIds } from "@/lib/authorization/resource-list";
import { validateInputs } from "@/lib/utils/validate";

export const getOrganizationsByUserId = reactCache(
  async (userId: string): Promise<{ id: string; name: string }[]> => {
    validateInputs([userId, ZString]);

    try {
      const organizationIds = await lookupAuthorizedOrganizationIds({ type: "user", id: userId });
      if (organizationIds.length === 0) return [];

      const organizations = await prisma.organization.findMany({
        where: {
          id: { in: [...organizationIds] },
        },
        // Deterministic order so callers that take organizations[0] (e.g. account settings'
        // default org) always resolve the same organization for a given user. id breaks ties when
        // two organizations share a createdAt timestamp.
        orderBy: [{ createdAt: "asc" }, { id: "asc" }],
        select: {
          id: true,
          name: true,
        },
      });
      if (!organizations) {
        throw new ResourceNotFoundError("Organizations by UserId", userId);
      }
      return organizations;
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) {
        throw new DatabaseError(error.message);
      }

      throw error;
    }
  }
);

